function parseCorrections(markdown) {
  const startMatch = markdown.match(/^## Correction Notices\s*$/m);
  if (!startMatch || startMatch.index == null) return [];

  // End at the authoritative ledger heading (exact line), not the working copy.
  const afterStart = startMatch.index + startMatch[0].length;
  const rest = markdown.slice(afterStart);
  const endIdxInRest = rest.search(/^## Transaction Ledger\s*$/m);
  const slice = endIdxInRest >= 0 ? rest.slice(0, endIdxInRest) : rest;

