        entry.value = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("effective:")) {
        entry.effective = trimmed.split(":")[1].trim();
      }
    }

    if (entry.transaction_id && entry.field && entry.value && entry.effective) {
      notices.push(entry);
    }
  }

  return notices;
}

module.exports = { parseCorrections };
