function parseCorrections(markdown) {
  const startMatch = markdown.match(/^## Correction Notices\s*$/m);
  if (!startMatch || startMatch.index == null) return [];

  // End at the authoritative ledger heading (exact line), not the working copy.
  const afterStart = startMatch.index + startMatch[0].length;
  const rest = markdown.slice(afterStart);
  const endIdxInRest = rest.search(/^## Transaction Ledger\s*$/m);
  const slice = endIdxInRest >= 0 ? rest.slice(0, endIdxInRest) : rest;

  const notices = [];
  const blocks = slice.split(/^### /m).slice(1);
  for (const block of blocks) {
    const lines = block.split("\n");
    const noticeId = (lines[0] || "").trim();
    if (!noticeId.startsWith("CORR-")) continue;

    const entry = { notice_id: noticeId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("targets:")) {
        entry.transaction_id = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("field:")) {
        entry.field = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("value:")) {
        entry.value = trimmed.split(":")[1].trim();
      } else if (trimmed.startsWith("effective:")) {
        entry.effective = trimmed.split(":")[1].trim();
      }
    }

    if (entry.transaction_id && entry.field && entry.value && entry.effective) {
      notices.push(entry);
    }
  }

  return notices;
}

module.exports = { parseCorrections };
